#include <stdio.h>

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    static long long a[1000005];
    for (int i = 0; i < N; ++i) {
        scanf("%lld", &a[i]);
    }

    int i = 0, j = N - 1;
    long long left = a[i], right = a[j];
    long long ops = 0;

    while (i < j) {
        if (left == right) {
            ++i;
            --j;
            if (i < j) {
                left = a[i];
                right = a[j];
            }
        } else if (left < right) {
            ++i;
            left += a[i];
            ++ops;
        } else {
            --j;
            right += a[j];
            ++ops;
        }
    }

    printf("%lld\n", ops);
    return 0;
}
